function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'TweetCounts' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with TweetCounts and no arguments.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls in total.';
  const isTime = t => Number.isInteger(t) && t >= 0 && t <= 1e9;
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (operations[i] === 'recordTweet') {
      if (!Array.isArray(call) || call.length !== 2 || typeof call[0] !== 'string') return 'recordTweet needs a tweet name and a time.';
      if (!isTime(call[1])) return 'time is an integer from 0 to 10^9.';
    } else if (operations[i] === 'getTweetCountsPerFrequency') {
      if (!Array.isArray(call) || call.length !== 4 || typeof call[1] !== 'string') return 'getTweetCountsPerFrequency needs freq, tweetName, startTime and endTime.';
      if (!['minute', 'hour', 'day'].includes(call[0])) return 'freq is "minute", "hour" or "day".';
      if (!isTime(call[2]) || !isTime(call[3])) return 'startTime and endTime are integers from 0 to 10^9.';
      if (call[3] < call[2] || call[3] - call[2] > 10000) return 'endTime - startTime is between 0 and 10^4.';
    } else return 'Only recordTweet and getTweetCountsPerFrequency can follow the constructor.';
  }
  return null;
}

