class TweetCounts {
  constructor() {
    this.times = new Map();
  }

  firstAtLeast(list, time) {
    let left = 0;
    let right = list.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (list[mid] < time) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  }

  recordTweet(tweetName, time) {
    if (!this.times.has(tweetName)) {
      this.times.set(tweetName, []);
    }
    const list = this.times.get(tweetName);
    list.splice(this.firstAtLeast(list, time), 0, time);
  }

  getTweetCountsPerFrequency(freq, tweetName, startTime, endTime) {
    const size = freq === 'minute' ? 60 : freq === 'hour' ? 3600 : 86400;
    const counts = new Array(Math.floor((endTime - startTime) / size) + 1).fill(0);
    const list = this.times.get(tweetName) ?? [];
    let index = this.firstAtLeast(list, startTime);
    while (index < list.length && list[index] <= endTime) {
      counts[Math.floor((list[index] - startTime) / size)]++;
      index++;
    }
    return counts;
  }
}

