class TweetCounts {
  // Keep every (name, time) pair and recount each slice from scratch.
  constructor() {
    this.log = [];
  }
  recordTweet(tweetName, time) {
    this.log.push([tweetName, time]);
  }
  getTweetCountsPerFrequency(freq, tweetName, startTime, endTime) {
    const length = { minute: 60, hour: 3600, day: 86400 }[freq];
    const result = [];
    for (let from = startTime; from <= endTime; from += length) {
      const to = Math.min(from + length - 1, endTime);
      let count = 0;
      for (const [name, time] of this.log) if (name === tweetName && time >= from && time <= to) count++;
      result.push(count);
    }
    return result;
  }
}

