function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const names = large ? ['tweet0', 'tweet1', 'tweet2', 'news', 'cat'] : ['a', 'b'];
  const freqs = ['minute', 'hour', 'day'];
  // Times cluster in a window so that queries actually see tweets.
  const span = large ? 20000 : 300;
  const base = large ? pick(1e9 - span + 1) : (rand() < 0.3 ? 1e9 - span : 0);
  const operations = ['TweetCounts'];
  const args = [[]];
  const calls = large ? 499 : 1 + pick(10);
  for (let c = 0; c < calls; c++) {
    const name = names[pick(names.length)];
    if (rand() < 0.65) {
      operations.push('recordTweet');
      args.push([name, base + pick(span + 1)]);
    } else {
      const width = rand() < 0.2 ? 0 : pick((large ? 10000 : 250) + 1);
      const startTime = base + pick(span - width + 1);
      operations.push('getTweetCountsPerFrequency');
      args.push([freqs[pick(3)], name, startTime, startTime + width]);
    }
  }
  return [operations, args];
}
